const j=require('./.claudinite/local/usage.GENERATED.json');
const F=j.fields;
console.log('1) version', j.version, '| generated', j.generated, '| ISO-parses:', !isNaN(Date.parse(j.generated)));
const hr=Object.entries(j.hours);
const decode=(tuple,fields)=>Object.fromEntries(fields.map((f,i)=>[f, tuple?.[i] ?? null]));
const schedIdx=F.hour.indexOf('scheduler');
const nz=hr.filter(([k,v])=> (v.totals??v)[schedIdx] > 0);
console.log('2) hour rows:', hr.length, '| with scheduler>0:', nz.length);
if(nz.length) console.log('   example', nz[0][0], JSON.stringify(decode(nz[0][1].totals ?? nz[0][1], F.hour)));
const days=Object.entries(j.days);
const ci=F.day.indexOf('commits'), la=F.day.indexOf('linesAdded'), lr=F.day.indexOf('linesRemoved');
const withCommits=days.filter(([d,t])=> t[ci]!==null && t[ci]!==undefined);
console.log('3) day rows:', days.length, '| carrying commits:', withCommits.length);
if(withCommits.length) console.log('   example', withCommits.at(-1)[0], JSON.stringify(decode(withCommits.at(-1)[1], F.day)));
const bad=days.filter(([d,t])=> (t[ci]===null||t[ci]===undefined) && ((t[la]??null)!==null || (t[lr]??null)!==null));
console.log('4) days with no commits key but a linesAdded/Removed value:', bad.length, bad.map(b=>b[0]).slice(0,5));
const zeros=days.filter(([d,t])=> t[ci]===0);
console.log('   days whose commits is literally 0 (a real zero, allowed):', zeros.length);
"

